cd packages/mendel-development && node -e "
const applyExtraOptions = require('./apply-extra-options');
const EventEmitter = require('events');
class FakeB extends EventEmitter {
  constructor() { super(); this._pending = 0; this._ignored = []; this._excluded = []; this._externals = []; }
  ignore(f) { this._ignored.push(f); }
  exclude(f) { this._excluded.push(f); }
  external(f, o) { this._externals.push([f, o]); }
}
const b = new FakeB();
b.on('_ready', () => {
  console.log('ready', b._ignored.length, b._excluded, b._externals);
});
b.on('error', (e) => console.error('ERROR', e));
applyExtraOptions(b, { ignore: ['*.js'], exclude: [], external: [] });
"

