13	class CacheClient extends EventEmitter {
14	    constructor({ cacheConnection, environment }, registry) {
15	        super();
16	
17	        this.registry = registry;
18	        this.environment = environment;
19	
20	        this.cacheConnection = cacheConnection;
21	        this.connected = false;
22	        this.synced = false;
23	        this.closeReqeusted = false;
24	        this.erroredEntries = new Map();
25	        this.connect();
26	    }
27	
28	    start() {
29	        if (this.connected) this.bootstrapConnection();
30	        else this.connection.once('connect', () => this.bootstrapConnection());
31	    }
32	
33	    onExit() {
34	        this.closeReqeusted = true;
35	        this.connection.end();
36	    }
37	
38	    onForceExit() {
39	        this.closeReqeusted = true;
40	        this.connection.end();
41	    }
42	
43	    connect(isRetry = false) {
44	        verbose('connecting with params', this.cacheConnection);
45	        const conn = network.getClient(this.cacheConnection);
46	        this.connection = conn;
47	        conn.on('error', (err) => !isRetry && this.emit('error', err));
48	        conn.on('data', (data) => {
49	            try {
50	                data = JSON.parse(data);
51	            } catch (e) {
52	                error(e);
53	            }
54	            if (!data || !data.type) return;
55	
56	            switch (data.type) {
57	                case 'addEntry': {
58	                    debugFilter(verbose, 'got ' + data.entry.id);
59	
60	                    this.registry.addEntry(data.entry);
61	                    this.erroredEntries.delete(data.entry.id);
62	
63	                    if (typeof data.totalEntries === 'number') {
64	                        this.checkStatus(data.totalEntries);
65	                    }
66	                    break;
67	                }
68	                case 'removeEntry': {
69	                    const unsynced = this.synced ? true : false;
70	                    this.synced = false;
71	                    this.registry.removeEntry(data.id);
72	                    this.erroredEntries.delete(data.id);
73	                    if (unsynced) this.emit('unsync', data.id);
