75	                    // Only a "final" removal (a real fs unlink, never
76	                    // followed by an addEntry) is safe to re-check status
77	                    // for here. A file being rebuilt also goes through
78	                    // removeEntry, and resyncing before its addEntry lands
79	                    // would let a request through against a bundle that's
80	                    // still missing that entry.
81	                    if (data.final && typeof data.totalEntries === 'number') {
82	                        this.checkStatus(data.totalEntries);
83	                    }
84	                    break;
85	                }
86	                case 'errorEntry': {
